#!/usr/bin/env python3
"""Generate the native multiplayer-world registry from import_all.MP_MAPS.

The checked-in header is deliberately boring.  Its value is that native code
never parses a map-name pattern or owns a second list: changing MP_MAPS makes
the freshness test fail until this file is regenerated.
"""
from __future__ import annotations

import argparse
import sys
from pathlib import Path


REPO = Path(__file__).resolve().parents[2]
IMPORT_DIR = REPO / "Tools" / "import"
sys.path.insert(0, str(IMPORT_DIR))

from import_all import MP_MAPS  # noqa: E402


def generate() -> bytes:
    names = tuple(MP_MAPS)
    if len(names) != 19 or len(set(names)) != len(names):
        raise ValueError("import_all.MP_MAPS is not the unique nineteen-map set")
    if any(not name or "." in name or "/" in name or "\\" in name
           for name in names):
        raise ValueError("import_all.MP_MAPS contains an unsafe package identity")
    rows = ",\n".join(
        f'\t{{TEXT("{name}"), TEXT("Maps/{name}.wot"), {index + 1}u}}'
        for index, name in enumerate(names))
    return f"""// Generated by Tools/dist/generate_world_registry.py; do not edit.
#pragma once

#include "CoreMinimal.h"

namespace WoT::Retail::Generated
{{
struct FRequiredWorld
{{
\tconst TCHAR* Identity;
\tconst TCHAR* SourcePath;
\tuint32 NeutralSlot;
}};

inline constexpr FRequiredWorld RequiredWorlds[] = {{
{rows}
}};
}}  // namespace WoT::Retail::Generated
""".encode("utf-8")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    try:
        expected = generate()
        if args.check:
            if args.output.read_bytes() != expected:
                print(f"world registry generated header is stale: {args.output}",
                      file=sys.stderr)
                return 1
        else:
            args.output.parent.mkdir(parents=True, exist_ok=True)
            args.output.write_bytes(expected)
    except (OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 2
    print(f"world registry header OK: {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
